from urllib.parse import urlparse, urlunparse
from typing import Dict, Any

DEFAULT_DASHBOARD = '/dashboard'

def build_post_login_redirect(next_url: str) -> Dict[str, Any]:
    parsed_url = urlparse(next_url)
    if parsed_url.netloc == '' and parsed_url.path.startswith('/'):
        target = urlunparse((parsed_url.scheme, '', parsed_url.path, parsed_url.params, parsed_url.query, parsed_url.fragment))
    else:
        target = DEFAULT_DASHBOARD
    return {"status": 302, "Location": target}

